import type { Question } from '../../lib/types'
export const network_performance_questions: Question[] = [
  { id: 'd3-net-001', domain: 3, topics: ['Transit Gateway', 'hub-and-spoke', 'VPC connectivity'], type: 'single', stem: 'A company has 50 VPCs needing full-mesh connectivity. VPC peering would require 1,225 connections. What simplifies this?', options: [{ id: 'A', text: 'Request a VPC peering limit increase from AWS Support to allow 1,225 connections' }, { id: 'B', text: 'AWS Transit Gateway' }, { id: 'C', text: 'VPC sharing via Resource Access Manager to merge all 50 VPCs into shared subnets' }, { id: 'D', text: 'Site-to-Site VPN connections between each pair of VPCs for secure private routing' }], correct: ['B'], explanation: 'Transit Gateway provides hub-and-spoke topology. Each VPC attaches to the TGW — n(n-1)/2 peering connections becomes n attachments. All VPCs communicate through the TGW.', distractors: { A: 'The peering limit is 125 per VPC — 50 VPCs still require 1,225 connections, which is operationally unmanageable.', C: 'VPC sharing shares subnets within an Organization — it does not provide routing between separate independent VPCs.', D: 'VPN between VPCs adds encryption overhead and latency — Transit Gateway is the scalable AWS-native solution.' } },
  { id: 'd3-net-002', domain: 3, topics: ['Direct Connect', 'dedicated connection', 'low latency'], type: 'single', stem: 'A financial application needs consistent low-latency connectivity to AWS. Internet VPN introduces too much jitter. What provides a private, consistent connection?', options: [{ id: 'A', text: 'Site-to-Site VPN with IKEv2 and DPD' }, { id: 'B', text: 'AWS Direct Connect' }, { id: 'C', text: 'EC2 Enhanced Networking (ENA)' }, { id: 'D', text: 'CloudFront with origin access to the on-premises application for caching latency-sensitive data' }], correct: ['B'], explanation: 'Direct Connect provides a dedicated private connection between on-premises and AWS, bypassing the public internet. Consistent latency, low jitter, up to 100 Gbps — essential for latency-sensitive financial workloads.', distractors: { A: 'VPN with IKEv2/DPD improves reliability — but still traverses the public internet with variable latency.', C: 'Enhanced Networking improves EC2 instance bandwidth within AWS — does not provide on-premises to AWS connectivity.', D: 'CloudFront caches and delivers content from edge locations — not a private enterprise network connection.' } },
  { id: 'd3-net-003', domain: 3, topics: ['Global Accelerator', 'anycast', 'AWS backbone'], type: 'single', stem: 'A global application needs to improve performance for users far from the AWS region. The solution should use the AWS private backbone instead of the public internet. What service does this?', options: [{ id: 'A', text: 'CloudFront CDN' }, { id: 'B', text: 'AWS Global Accelerator' }, { id: 'C', text: 'Route 53 latency routing' }, { id: 'D', text: 'NAT Gateway in each region' }], correct: ['B'], explanation: 'Global Accelerator uses Anycast IPs to route user traffic to the nearest AWS edge location, then routes over the AWS private backbone to the application region. Avoids public internet congestion for the majority of the path.', distractors: { A: 'CloudFront caches content at edges — suited for static assets, not routing arbitrary application TCP/UDP traffic.', C: 'Route 53 latency routing uses DNS to select a regional endpoint — still uses the public internet for the actual network path.', D: 'NAT Gateway provides outbound internet access for private instances — not a performance acceleration service.' } },
  { id: 'd3-net-004', domain: 3, topics: ['PrivateLink', 'VPC Endpoint Services', 'cross-account'], type: 'single', stem: 'A company hosts an API in their VPC and wants customers from other VPCs and accounts to access it privately without internet exposure or VPC peering. What enables this?', options: [{ id: 'A', text: 'VPC peering for each customer VPC' }, { id: 'B', text: 'AWS PrivateLink' }, { id: 'C', text: 'Internet Gateway with security group' }, { id: 'D', text: 'Site-to-Site VPN for each customer' }], correct: ['B'], explanation: 'AWS PrivateLink exposes a service via a Network Load Balancer. Consumers create an Interface Endpoint (ENI) in their VPC. Traffic flows within the AWS network — no internet, no VPC peering, no overlapping CIDR concern.', distractors: { A: 'VPC peering requires non-overlapping CIDRs and shares full routing between VPCs — PrivateLink provides targeted one-way service access.', C: 'Internet Gateway exposes the service publicly — not a private connectivity solution for cross-account access.', D: 'Site-to-Site VPN connects on-premises to AWS — not designed for VPC-to-VPC service access across accounts.' } },
  { id: 'd3-net-005', domain: 3, topics: ['Direct Connect', 'LAG', 'bandwidth aggregation'], type: 'single', stem: 'A company has a 1 Gbps Direct Connect connection and needs more bandwidth by aggregating multiple connections. What bonds multiple Direct Connect connections into one?', options: [{ id: 'A', text: 'Increase the MTU of the existing Direct Connect connection to allow larger frames' }, { id: 'B', text: 'Direct Connect Link Aggregation Group (LAG)' }, { id: 'C', text: 'Add a second Virtual Private Gateway and split traffic between them for parallel throughput' }, { id: 'D', text: 'Direct Connect Gateway' }], correct: ['B'], explanation: 'Direct Connect LAG combines multiple physical connections (same speed, same DX location) into one logical interface. 4 × 1 Gbps = 4 Gbps LAG. Active-active for load balancing; failure of one connection reduces but doesn\'t eliminate bandwidth.', distractors: { A: 'MTU setting affects packet sizes — does not increase aggregate bandwidth capacity.', C: 'Multiple VGWs provide separate routing domains — they do not aggregate bandwidth from a single DX connection.', D: 'Direct Connect Gateway enables cross-region VPC connectivity — not a bandwidth aggregation feature.' } },
  { id: 'd3-net-006', domain: 3, topics: ['Transit Gateway', 'multicast', 'one-to-many'], type: 'single', stem: 'A media company streams a single live video to thousands of EC2 instances without sending individual copies to each. What Transit Gateway feature supports native multicast?', options: [{ id: 'A', text: 'Transit Gateway standard unicast routing' }, { id: 'B', text: 'Transit Gateway multicast' }, { id: 'C', text: 'CloudFront with HLS/DASH streaming' }, { id: 'D', text: 'VPC peering between each sender-receiver pair' }], correct: ['B'], explanation: 'Transit Gateway multicast enables multicast routing across VPC attachments. A single stream is replicated by the network infrastructure rather than by the sender — reduces bandwidth at the source and eliminates application-level fan-out.', distractors: { A: 'Unicast routing requires the sender to create individual copies for each receiver — does not scale to thousands of instances.', C: 'CloudFront delivers cached HTTP content to browsers — not real-time multicast for EC2 instance-to-instance data distribution.', D: 'VPC peering is non-transitive and unicast — does not provide multicast routing capabilities.' } },
  { id: 'd3-net-007', domain: 3, topics: ['VPC peering', 'AWS backbone', 'private routing'], type: 'single', stem: 'Does VPC peering traffic between two VPCs travel over the public internet?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'No' }, { id: 'C', text: 'VPC peering only works within the same Availability Zone' }, { id: 'D', text: 'VPC peering uses a VPN tunnel within the AWS network for encrypted private transport' }], correct: ['B'], explanation: 'VPC peering traffic always stays on the AWS global network backbone. It never traverses the public internet. Provides consistent, low-latency, high-bandwidth private connectivity between VPCs.', distractors: { A: 'VPC peering uses the AWS private network — not the public internet, regardless of whether VPCs are in different regions.', C: 'VPC peering works cross-AZ and cross-region (inter-region peering) — it is not limited to a single AZ.', D: 'VPC peering is direct routing at the network layer — no VPN tunnels are involved.' } },
  { id: 'd3-net-008', domain: 3, topics: ['Direct Connect', 'Public VIF', 'AWS public services'], type: 'single', stem: 'A company with Direct Connect wants to access AWS public services (S3, DynamoDB) over the DX connection without internet routing. Which VIF type enables this?', options: [{ id: 'A', text: 'Private VIF' }, { id: 'B', text: 'Public VIF' }, { id: 'C', text: 'Transit VIF' }, { id: 'D', text: 'Hosted VIF from a Direct Connect partner' }], correct: ['B'], explanation: 'Public VIF connects to AWS public service endpoints (S3, EC2 public IPs, DynamoDB, etc.) using AWS public IP addresses, but traffic flows over the DX private link — not the internet. Provides private access to public AWS services.', distractors: { A: 'Private VIF connects to a specific VPC via VGW — not to public AWS services.', C: 'Transit VIF connects to Transit Gateway for multi-VPC routing — not for accessing public AWS service endpoints.', D: 'Hosted VIF is a sharing arrangement from a partner — the VIF type (public/private/transit) still determines what it connects to.' } },
  { id: 'd3-net-009', domain: 3, topics: ['Accelerated VPN', 'Global Accelerator', 'VPN latency'], type: 'single', stem: 'International offices using Site-to-Site VPN to AWS experience high latency. What optimization routes VPN traffic through AWS edge locations?', options: [{ id: 'A', text: 'Increase VPN tunnel bandwidth allocation in the VPN configuration settings' }, { id: 'B', text: 'Accelerated Site-to-Site VPN' }, { id: 'C', text: 'Deploy Direct Connect connections at each international office location' }, { id: 'D', text: 'Configure split tunneling to route non-AWS traffic directly to the internet without the VPN' }], correct: ['B'], explanation: 'Accelerated Site-to-Site VPN routes VPN traffic from the office through the nearest AWS Global Accelerator edge location, then over the AWS backbone to the VPC. Reduces the internet segment of the path significantly.', distractors: { A: 'VPN bandwidth is determined by the internet link — AWS does not provide configurable per-tunnel bandwidth allocation.', C: 'Direct Connect at each office requires physical hardware installation and procurement — not a quick optimization.', D: 'Split tunneling routes non-AWS traffic directly — it reduces VPN load but does not improve the VPN path latency itself.' } },
  { id: 'd3-net-010', domain: 3, topics: ['VPC peering', 'non-transitive', 'Transit Gateway'], type: 'single', stem: 'VPC A peers with VPC B. VPC B peers with VPC C. Can VPC A reach VPC C through VPC B?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'No' }, { id: 'C', text: 'Yes, but only with specific route table entries pointing A\'s traffic through B\'s CIDR range' }, { id: 'D', text: 'Yes, if VPC B has route propagation enabled on both its peering connections' }], correct: ['B'], explanation: 'VPC peering is non-transitive — a fundamental exam concept. VPC A can only communicate with directly peered VPC B. For A-C communication: create a direct A-C peering or use Transit Gateway which supports transitive routing.', distractors: { A: 'Transitive routing through VPC peering is explicitly not supported by AWS — it is an architectural limitation, not a configuration issue.', C: 'Route tables cannot enable transitive peering — even with the correct routes, VPC B will not forward A\'s packets to C.', D: 'Route propagation applies to VGW routes — it does not enable transitive VPC peering.' } },
  { id: 'd3-net-011', domain: 3, topics: ['CloudFront', 'Origin Shield', 'cache layer'], type: 'single', stem: 'A CloudFront distribution has many edge locations generating cache-miss requests to an S3 origin. What adds a regional caching layer to reduce origin requests?', options: [{ id: 'A', text: 'Increase CloudFront default TTL' }, { id: 'B', text: 'CloudFront Origin Shield' }, { id: 'C', text: 'Add more CloudFront edge locations' }, { id: 'D', text: 'Deploy multiple S3 origins with CRR' }], correct: ['B'], explanation: 'Origin Shield acts as a centralized cache between all global edge locations and the origin. Cache misses from edges check Origin Shield first — significantly reduces total origin requests and bandwidth costs.', distractors: { A: 'Longer TTL helps for cacheable content — Origin Shield helps regardless of TTL by consolidating cache misses to one regional layer.', C: 'More edge locations distribute user traffic — they do not reduce the total number of origin cache misses.', D: 'Multiple S3 origins add redundancy — they do not reduce per-origin request volume from CloudFront edges.' } },
  { id: 'd3-net-012', domain: 3, topics: ['AWS Network Firewall', 'DPI', 'stateful inspection'], type: 'single', stem: 'A company needs deep packet inspection and stateful firewall rules for all VPC traffic at high throughput without managing firewall infrastructure. What provides this?', options: [{ id: 'A', text: 'Security Groups' }, { id: 'B', text: 'AWS Network Firewall' }, { id: 'C', text: 'Network ACLs' }, { id: 'D', text: 'AWS WAF' }], correct: ['B'], explanation: 'AWS Network Firewall is a managed VPC-level inspection service: deep packet inspection, IPS/IDS rules (Suricata), stateful connection tracking, domain filtering, TLS inspection. Scales automatically to handle Gbps traffic.', distractors: { A: 'Security groups provide stateful allow rules at instance level — no deep packet inspection or signature-based IPS rules.', C: 'NACLs provide stateless subnet-level filtering — no deep packet inspection or IPS capabilities.', D: 'WAF handles HTTP/HTTPS application-layer attacks — not general network deep packet inspection for all protocols.' } },
  { id: 'd3-net-013', domain: 3, topics: ['Gateway Load Balancer', 'inline inspection', 'GENEVE'], type: 'single', stem: 'A company wants to route all VPC traffic through third-party NGFW appliances for inspection without modifying applications. What provides transparent inline appliance insertion?', options: [{ id: 'A', text: 'ALB with appliance target groups' }, { id: 'B', text: 'Gateway Load Balancer (GWLB)' }, { id: 'C', text: 'NLB in front of appliances' }, { id: 'D', text: 'Transit Gateway policy-based routing' }], correct: ['B'], explanation: 'GWLB is designed for inline appliance insertion. Using GENEVE encapsulation, it distributes traffic to appliances (preserving original IP headers), receives inspected traffic back, and returns it to the original destination — transparent to applications.', distractors: { A: 'ALB requires changing application routing to point to appliances — not transparent inline inspection.', C: 'NLB routes to appliances but does not handle the symmetric return path for inline inspection transparently.', D: 'TGW policy routing steers traffic into inspection VPCs — GWLB handles the actual load balancing and return path.' } },
  { id: 'd3-net-014', domain: 3, topics: ['Transit Gateway', 'ECMP', 'VPN throughput'], type: 'single', stem: 'A Site-to-Site VPN provides up to 1.25 Gbps per tunnel. A company needs more than 1.25 Gbps VPN throughput. What configuration scales VPN bandwidth?', options: [{ id: 'A', text: 'Use a larger Virtual Private Gateway for higher per-tunnel throughput capacity' }, { id: 'B', text: 'Transit Gateway with multiple VPN connections and ECMP' }, { id: 'C', text: 'Configure a Dedicated Host as the VPN termination endpoint for higher bandwidth' }, { id: 'D', text: 'Switch from IPsec to TLS-based VPN for higher throughput per tunnel' }], correct: ['B'], explanation: 'Transit Gateway supports ECMP routing across multiple VPN connections. With 4 VPN connections and ECMP enabled, you can achieve ~5 Gbps. Each VPN connection has two tunnels (active-active with ECMP = 2.5 Gbps per VPN).', distractors: { A: 'There is no larger VGW option — VGW is a managed service with a fixed 1.25 Gbps per tunnel limit.', C: 'Dedicated Hosts are for EC2 licensing requirements — they do not provide VPN termination or higher tunnel throughput.', D: 'AWS Site-to-Site VPN uses IPsec — TLS VPN is a different product category not available as a VGW feature.' } },
  { id: 'd3-net-015', domain: 3, topics: ['Route 53', 'TTL', 'DNS resolution latency'], type: 'single', stem: 'An application uses Route 53 with a 60-second TTL. Users whose DNS cache expires frequently experience additional latency per request. What reduces DNS query frequency?', options: [{ id: 'A', text: 'Increase TTL to 300-3600 seconds' }, { id: 'B', text: 'Enable Route 53 Resolver DNS Firewall' }, { id: 'C', text: 'Enable Route 53 query logging to CloudWatch' }, { id: 'D', text: 'DNS cache expiry is controlled by the user\'s OS' }], correct: ['A'], explanation: 'Longer TTL reduces DNS query frequency — local resolvers cache the answer longer before querying Route 53 again. For stable endpoints, increase TTL (e.g., 300-3600 seconds). Trade-off: slower DNS change propagation.', distractors: { B: 'DNS Firewall filters queries for security purposes — does not extend cache duration or reduce query frequency.', C: 'Query logging provides observability — does not improve DNS performance or cache behavior.', D: 'TTL directly controls how long resolvers cache responses — Route 53 TTL does affect resolution frequency at the resolver level.' } },
  { id: 'd3-net-016', domain: 3, topics: ['VPC', 'multi-AZ', 'AZ resilience'], type: 'single', stem: 'A company deploys EC2 instances in a single subnet in one AZ. What is the minimum architecture change for AZ fault tolerance?', options: [{ id: 'A', text: 'Add a second EC2 instance in the same AZ subnet for redundancy within the zone' }, { id: 'B', text: 'Create subnets in 2+ AZs and deploy instances across them with an ALB distributing traffic' }, { id: 'C', text: 'Enable enhanced networking (ENA) on the existing instances for more reliable connectivity' }, { id: 'D', text: 'Upgrade to a larger instance type to handle failures without additional capacity' }], correct: ['B'], explanation: 'AZ resilience requires distributing instances across multiple AZs. Create subnets in 2+ AZs, deploy instances in each, use an ALB/NLB to distribute traffic. If one AZ fails, instances in other AZs continue serving.', distractors: { A: 'Multiple instances in the same AZ all fail together when that AZ has an outage.', C: 'Enhanced networking improves bandwidth performance — does not provide redundancy against AZ failures.', D: 'A larger instance in a single AZ still fails completely during an AZ outage.' } },
  { id: 'd3-net-017', domain: 3, topics: ['Transit Gateway', 'route tables', 'network segmentation'], type: 'single', stem: 'Production and development VPCs are attached to a Transit Gateway. Production VPCs must not communicate with development VPCs. How is this enforced?', options: [{ id: 'A', text: 'Transit Gateway does not support network segmentation' }, { id: 'B', text: 'Separate TGW route tables for prod and dev' }, { id: 'C', text: 'Security groups on EC2 instances' }, { id: 'D', text: 'Create separate Transit Gateways for prod and dev' }], correct: ['B'], explanation: 'TGW route tables provide network segmentation. Associate production VPCs with a prod route table (no routes to dev VPCs) and dev VPCs with a dev route table (no routes to prod VPCs). One TGW, isolated routing domains.', distractors: { A: 'Transit Gateway route tables are specifically the mechanism for network segmentation — it is a core TGW capability.', C: 'Security groups are instance-level — they can restrict traffic but do not prevent network-layer routing between VPCs.', D: 'Separate TGWs work but are more expensive and complex — TGW route tables solve this within one TGW.' } },
  { id: 'd3-net-018', domain: 3, topics: ['CloudFront', 'automatic compression', 'Brotli'], type: 'single', stem: 'A CloudFront distribution serves HTML, CSS, and JavaScript. Clients support gzip and Brotli. How does CloudFront reduce file transfer sizes automatically?', options: [{ id: 'A', text: 'CloudFront does not support compression' }, { id: 'B', text: 'Enable CloudFront automatic compression' }, { id: 'C', text: 'Pre-compress all files in S3 before upload' }, { id: 'D', text: 'Use HTTP/3 with QUIC' }], correct: ['B'], explanation: 'CloudFront automatically compresses eligible files (HTML, CSS, JS, JSON) using gzip or Brotli when clients send Accept-Encoding headers. Compression at the edge — reduces transferred bytes. CloudFront caches both versions.', distractors: { A: 'CloudFront does support automatic compression — it is a cache behavior setting, not a limitation.', C: 'Pre-compressed S3 files work but require S3 changes — CloudFront auto-compression handles it at the edge without modifying origin files.', D: 'HTTP/3 QUIC provides transport-layer improvements — content-level compression (gzip/Brotli) is separate from the transport protocol.' } },
  { id: 'd3-net-019', domain: 3, topics: ['Direct Connect', 'HA', 'redundancy'], type: 'single', stem: 'A company has one Direct Connect connection. What is the minimum additional infrastructure for HA against single DX connection failure?', options: [{ id: 'A', text: 'Add a second Virtual Private Gateway' }, { id: 'B', text: 'A second Direct Connect connection (different device) for active-active or active-passive redundancy' }, { id: 'C', text: 'Enable Multi-AZ mode on the Direct Connect connection for automatic failover between AZs' }, { id: 'D', text: 'Increase the bandwidth of the existing connection' }], correct: ['B'], explanation: 'AWS recommends two Direct Connect connections to separate devices (ideally different DX locations) for HA. Active-active for load sharing; if one fails, the other carries all traffic. Add VPN as backup for cost-constrained setups.', distractors: { A: 'A second VGW provides routing options — but does not protect against the physical DX connection itself failing.', C: 'Direct Connect is a physical connection at a specific location — there is no Multi-AZ mode for a DX connection.', D: 'More bandwidth on one connection does not protect against that connection completely failing.' } },
  { id: 'd3-net-020', domain: 3, topics: ['VPC Flow Logs', 'packet drops', 'network troubleshooting'], type: 'single', stem: 'A network team investigates intermittent packet drops in a VPC. Which tool captures accepted and rejected traffic for analysis?', options: [{ id: 'A', text: 'CloudTrail API logs' }, { id: 'B', text: 'VPC Flow Logs' }, { id: 'C', text: 'AWS X-Ray' }, { id: 'D', text: 'CloudWatch application metrics' }], correct: ['B'], explanation: 'VPC Flow Logs record all IP traffic: source/dest IP, port, protocol, ACCEPT/REJECT action, bytes transferred. Sent to CloudWatch Logs or S3. Essential for diagnosing packet drops, security analysis, and compliance.', distractors: { A: 'CloudTrail logs AWS API management calls — not packet-level IP network traffic within VPCs.', C: 'X-Ray traces application-level request flows — not network packet-level analysis.', D: 'CloudWatch metrics show aggregate service-level metrics — not per-flow packet drop or accept/reject analysis.' } },
  { id: 'd3-net-021', domain: 3, topics: ['Transit Gateway Connect', 'SD-WAN', 'GRE'], type: 'single', stem: 'A company uses SD-WAN appliances in their VPC for branch connectivity. They need to connect SD-WAN to TGW with up to 20 Gbps without Direct Connect hardware. What enables this?', options: [{ id: 'A', text: 'VPN attachment (IPsec)' }, { id: 'B', text: 'Transit Gateway Connect' }, { id: 'C', text: 'Direct Connect Transit VIF' }, { id: 'D', text: 'VPC Peering between the SD-WAN VPC and destination VPCs for direct private routing' }], correct: ['B'], explanation: 'TGW Connect attachment uses GRE (Generic Routing Encapsulation) for high-bandwidth connectivity between TGW and SD-WAN/virtual appliances running in a VPC. Up to 20 Gbps per Connect attachment.', distractors: { A: 'VPN/IPsec to TGW is limited to 1.25 Gbps per tunnel — insufficient for high-bandwidth SD-WAN requirements.', C: 'Direct Connect Transit VIF requires physical hardware at a DX location — virtual appliances in a VPC use TGW Connect.', D: 'VPC Peering provides VPC-level connectivity — not a SD-WAN-to-TGW attachment with BGP peering.' } },
  { id: 'd3-net-022', domain: 3, topics: ['VPC Reachability Analyzer', 'connectivity debugging'], type: 'single', stem: 'A developer cannot connect to an EC2 instance. Security groups, NACLs, and route tables may all have errors. What tool identifies the specific blocking component without sending test traffic?', options: [{ id: 'A', text: 'VPC Flow Logs' }, { id: 'B', text: 'VPC Reachability Analyzer' }, { id: 'C', text: 'AWS X-Ray' }, { id: 'D', text: 'CloudWatch network metrics' }], correct: ['B'], explanation: 'VPC Reachability Analyzer analyzes the network topology between a source and destination. Identifies which specific security group rule, NACL, route table entry, or missing IGW is blocking the path — without generating test traffic.', distractors: { A: 'Flow Logs show actual traffic (or absence) — Reachability Analyzer performs pre-traffic topology analysis to find misconfigurations.', C: 'X-Ray traces application-level distributed requests — not network topology and connectivity analysis.', D: 'CloudWatch ENI metrics show aggregates — not which specific security group or NACL rule is causing the block.' } },
  { id: 'd3-net-023', domain: 3, topics: ['PrivateLink', 'Private DNS', 'interface endpoint'], type: 'single', stem: 'An EC2 instance uses a VPC Interface Endpoint for S3. DNS for s3.amazonaws.com should resolve to the endpoint private IP. What configuration is required?', options: [{ id: 'A', text: 'No configuration needed' }, { id: 'B', text: 'Enable Private DNS on the Interface Endpoint' }, { id: 'C', text: 'Add a custom Route 53 private hosted zone record for s3.amazonaws.com pointing to the endpoint IP' }, { id: 'D', text: 'Update /etc/hosts on each EC2 instance to map s3.amazonaws.com to the endpoint private IP' }], correct: ['B'], explanation: 'Enable Private DNS on the Interface Endpoint. The VPC\'s Route 53 Resolver returns the endpoint ENI IP for s3.amazonaws.com queries from within the VPC. No application changes — the service hostname resolves to the private endpoint automatically.', distractors: { A: 'Private DNS is not enabled by default — it must be explicitly enabled when creating or modifying the endpoint.', C: 'Custom Route 53 records require manual lifecycle management alongside the endpoint — Private DNS handles this automatically.', D: '/etc/hosts modifications require updating every instance and do not scale or update automatically.' } },
  { id: 'd3-net-024', domain: 3, topics: ['CloudFront', 'HTTP/3', 'QUIC', 'mobile performance'], type: 'single', stem: 'A mobile app using CloudFront has poor performance on high-latency mobile networks. HTTP/2 is enabled. What newer protocol reduces connection latency further?', options: [{ id: 'A', text: 'HTTP/1.1 with connection keep-alive' }, { id: 'B', text: 'HTTP/3 (QUIC)' }, { id: 'C', text: 'WebSocket connections for all requests' }, { id: 'D', text: 'TLS 1.3 only' }], correct: ['B'], explanation: 'HTTP/3 (QUIC) uses UDP. Benefits: 0-RTT connection resumption, no head-of-line blocking (packet loss affects one stream not all), better on lossy mobile networks. CloudFront supports HTTP/3 as an opt-in setting.', distractors: { A: 'HTTP/1.1 is an older protocol than HTTP/2 — it would not improve performance over already-enabled HTTP/2.', C: 'WebSocket is for persistent bidirectional data channels — not a general HTTP performance protocol for request/response.', D: 'TLS 1.3 reduces handshake round trips — HTTP/3 QUIC provides additional protocol-level improvements beyond TLS version.' } },
  { id: 'd3-net-025', domain: 3, topics: ['NAT Gateway', 'bandwidth', 'multi-AZ scaling'], type: 'single', stem: 'Private EC2 instances use NAT Gateway for internet access. Outbound bandwidth consistently hits the 45 Gbps NAT Gateway limit. How can more throughput be achieved?', options: [{ id: 'A', text: 'NAT Gateways automatically scale beyond 45 Gbps' }, { id: 'B', text: 'Create NAT Gateways in multiple AZs and distribute instances across AZs' }, { id: 'C', text: 'Enable enhanced networking on the NAT Gateway for higher bandwidth capacity' }, { id: 'D', text: 'Replace NAT Gateway with an Internet Gateway for private subnet egress bandwidth above 45 Gbps' }], correct: ['B'], explanation: 'Each NAT Gateway provides up to 45 Gbps. Distribute instances across multiple AZs, each with its own NAT Gateway. Instances in each AZ route through their AZ\'s NAT GW — aggregate throughput scales with the number of AZs.', distractors: { A: 'NAT Gateways do not auto-scale beyond 45 Gbps per gateway — adding more gateways in more AZs is the scaling pattern.', C: 'NAT Gateways are fully managed services — there are no user-configurable network settings like enhanced networking.', D: 'Internet Gateways route traffic between VPCs and the internet — private instances without public IPs cannot use IGW directly.' } },
  { id: 'd3-net-026', domain: 3, topics: ['Site-to-Site VPN', 'DPD', 'IKEv2', 'reliability'], type: 'single', stem: 'Site-to-Site VPN tunnels frequently drop without notification, requiring manual restart. What VPN features improve tunnel reliability?', options: [{ id: 'A', text: 'Use route-based VPN (BGP) instead of policy-based routing' }, { id: 'B', text: 'Enable Dead Peer Detection (DPD) and IKEv2' }, { id: 'C', text: 'Increase the IKE encryption key size to 4096-bit for more stable tunnel negotiation' }, { id: 'D', text: 'Enable BGP dynamic routing' }], correct: ['B'], explanation: 'Dead Peer Detection sends periodic keepalives. When no response after DPD timeout, the VPN automatically reinitiates the tunnel. IKEv2 provides more efficient re-keying and faster recovery than IKEv1.', distractors: { A: 'Route-based VPN with BGP provides flexible routing — BGP keepalives detect routing failures but DPD specifically handles tunnel-level dead peer detection.', C: 'Larger encryption keys increase CPU overhead — they do not improve tunnel stability or failure detection.', D: 'BGP keepalives detect routing adjacency loss — DPD specifically monitors the IPsec tunnel peer and restarts it automatically.' } },
  { id: 'd3-net-027', domain: 3, topics: ['inter-region peering', 'data transfer cost'], type: 'single', stem: 'A company uses inter-region VPC peering between us-east-1 and eu-west-1. What is the cost implication of this data transfer?', options: [{ id: 'A', text: 'Inter-region VPC peering data transfer is free' }, { id: 'B', text: 'Inter-region peering data transfer is charged at standard cross-region rates (~$0.02/GB per direction)' }, { id: 'C', text: 'Only inbound data transfer to the VPC is charged' }, { id: 'D', text: 'Data transfer is free within the AWS network' }], correct: ['B'], explanation: 'Cross-region data transfer over VPC peering is NOT free. Standard inter-region rates apply in both directions. Same-region peering data transfer within the same AZ IS free. Cost optimization: minimize cross-region data movement.', distractors: { A: 'Same-region intra-AZ peering is free — cross-region peering incurs standard inter-region data transfer charges.', C: 'Both inbound and outbound inter-region data transfer are charged — there is no free direction for cross-region.', D: '"Within the AWS network" does not mean free — cross-region data transfer charges apply even on the AWS backbone.' } },
  { id: 'd3-net-028', domain: 3, topics: ['CloudFront', 'cache key', 'cookie forwarding'], type: 'single', stem: 'A CloudFront distribution is not caching responses because the app sets many cookies (auth, tracking, preferences). How can caching be improved without breaking authentication?', options: [{ id: 'A', text: 'Remove all cookies from the application' }, { id: 'B', text: 'Configure cache policy to include only content-affecting cookies in the cache key; exclude tracking cookies' }, { id: 'C', text: 'Disable cookie forwarding entirely' }, { id: 'D', text: 'Use signed cookies for all requests' }], correct: ['B'], explanation: 'Configure the cache policy to include only cookies that affect content (e.g., language, user-tier) in the cache key. Exclude analytics/tracking cookies. Separate cache key decisions (what determines the response) from cookies forwarded to origin.', distractors: { A: 'Removing cookies breaks authentication and personalization — the goal is selective cookie forwarding.', C: 'Disabling all cookie forwarding breaks authentication for protected content — selective forwarding is the solution.', D: 'Signed cookies control access authorization — not a mechanism for improving general cache hit rates.' } },
  { id: 'd3-net-029', domain: 3, topics: ['VPC routing', 'longest prefix match'], type: 'single', stem: 'A route table has 10.0.0.0/8 → Transit Gateway and 10.1.0.0/16 → VPC Peering. A packet destined for 10.1.2.3 — which route wins?', options: [{ id: 'A', text: '10.0.0.0/8 → Transit Gateway' }, { id: 'B', text: '10.1.0.0/16 → VPC Peering' }, { id: 'C', text: 'The packet is dropped' }, { id: 'D', text: 'Both routes are used and traffic is load balanced across Transit Gateway and VPC Peering' }], correct: ['B'], explanation: 'IP routing uses longest prefix match: the most specific (longest prefix length) matching route wins. 10.1.0.0/16 (/16 is more specific than /8) matches 10.1.2.3 — VPC Peering route is selected.', distractors: { A: 'Route table order does not determine selection — longest prefix match is the rule, not the entry order.', C: 'Overlapping routes are valid — longest prefix match deterministically resolves the selection without conflict.', D: 'IP routing selects exactly one route — it does not load balance across multiple overlapping routes.' } },
  { id: 'd3-net-030', domain: 3, topics: ['ALB', 'deregistration delay', 'connection draining'], type: 'single', stem: 'During Auto Scaling scale-in events, EC2 instances terminate with active connections open, causing request errors. What ALB feature gracefully handles this?', options: [{ id: 'A', text: 'ALB health checks' }, { id: 'B', text: 'Deregistration delay' }, { id: 'C', text: 'Sticky sessions' }, { id: 'D', text: 'ALB multi-value headers' }], correct: ['B'], explanation: 'Deregistration delay (connection draining) allows in-flight requests to complete. ALB stops sending NEW requests to deregistering instances but allows existing connections to finish, up to the timeout (default 300s, range 0-3600s).', distractors: { A: 'Health checks determine if an instance is healthy — deregistration delay controls how existing connections are handled when an instance intentionally deregisters.', C: 'Sticky sessions bind users to instances — during termination, they cause all stuck sessions to fail rather than gracefully draining.', D: 'Multi-value headers allows multiple HTTP header values — not related to connection draining during instance deregistration.' } },
  { id: 'd3-net-031', domain: 3, topics: ['Direct Connect Gateway', 'multi-region', 'multi-VPC'], type: 'single', stem: 'A company has Direct Connect and VPCs in multiple regions. How can a single DX connection access VPCs in all regions?', options: [{ id: 'A', text: 'Create a separate Virtual Private Gateway per VPC and private VIF for each' }, { id: 'B', text: 'Direct Connect Gateway' }, { id: 'C', text: 'Create Site-to-Site VPN connections from the DX-connected VPC to VPCs in other regions' }, { id: 'D', text: 'Use cross-region VPC peering from the DX-connected VPC to reach all other regional VPCs' }], correct: ['B'], explanation: 'Direct Connect Gateway provides global connectivity: one private VIF → DX Gateway → associated with VGWs or TGWs in multiple regions. A single DX connection can reach up to 10 TGWs or 20 VGWs across regions.', distractors: { A: 'One VGW + private VIF per VPC is limited to VPCs in the same region as the DX connection — DX Gateway is cross-region.', C: 'VPN from the DX-connected VPC to other regions adds complexity and latency — DX Gateway provides native cross-region access.', D: 'Cross-region peering requires additional routing hops and doesn\'t allow on-premises traffic to route through peered VPCs.' } },
  { id: 'd3-net-032', domain: 3, topics: ['NACL', 'stateless', 'ephemeral ports'], type: 'single', stem: 'An EC2 instance sends outbound requests to the internet. The NACL has no inbound rule for return traffic. Why are responses blocked?', options: [{ id: 'A', text: 'NACLs are stateful' }, { id: 'B', text: 'NACLs are stateless' }, { id: 'C', text: 'The Internet Gateway is filtering return traffic before it reaches the NACL' }, { id: 'D', text: 'Security groups are blocking the return traffic' }], correct: ['B'], explanation: 'NACLs are stateless — outbound requests do not create state for return traffic. Return traffic arrives on ephemeral (random high) ports. The NACL must explicitly allow inbound on ports 1024-65535 for response packets.', distractors: { A: 'Security groups are stateful (return traffic automatically allowed) — NACLs are stateless, requiring explicit rules for both directions.', C: 'Internet Gateways do not filter traffic — they route packets between VPC and internet. NACLs are the filtering layer.', D: 'Security groups are stateful — they automatically allow return traffic. The stateless NACL is the blocking component here.' } },
  { id: 'd3-net-033', domain: 3, topics: ['CloudFront', 'geo restriction', 'geographic blocking'], type: 'single', stem: 'A streaming service must block content delivery to specific countries due to licensing restrictions. What CloudFront feature enforces this?', options: [{ id: 'A', text: 'Route 53 geolocation routing' }, { id: 'B', text: 'CloudFront geo restriction' }, { id: 'C', text: 'AWS WAF with geographic match rule' }, { id: 'D', text: 'Lambda@Edge viewer request function' }], correct: ['B'], explanation: 'CloudFront geo restriction uses a whitelist (allow only listed countries) or blacklist (block listed countries) based on viewer IP → country. Simple configuration-only feature — no code needed.', distractors: { A: 'Route 53 geolocation routing directs DNS queries — it does not restrict CloudFront content delivery at the edge.', C: 'WAF geographic match works but adds cost and complexity — CloudFront native geo restriction is simpler for straightforward blocking.', D: 'Lambda@Edge can do custom geolocation — but CloudFront geo restriction is built-in configuration, no code needed.' } },
  { id: 'd3-net-034', domain: 3, topics: ['security groups', 'SG reference', 'dynamic IP'], type: 'single', stem: 'A web tier security group should allow inbound traffic only from the ALB. The ALB IPs change as it scales. What rule source avoids hardcoding IPs?', options: [{ id: 'A', text: 'Allow inbound from the ALB\'s Elastic IP address' }, { id: 'B', text: 'Reference the ALB security group ID as the source' }, { id: 'C', text: 'Allow all inbound from 0.0.0.0/0 and rely on ALB to only forward legitimate requests' }, { id: 'D', text: 'Use NACL rules matching the ALB subnet CIDR' }], correct: ['B'], explanation: 'Security groups can reference other security groups as the source. Allows traffic from all resources in the referenced security group — automatically adapts as ALB nodes are added or replaced. No IP maintenance needed.', distractors: { A: 'ALBs do not support Elastic IPs — ALB IPs change dynamically as the load balancer scales.', C: '0.0.0.0/0 allows all internet traffic — not restricted to the ALB only.', D: 'NACL CIDR rules covering the ALB subnet are static — traffic from other resources in that subnet would also be allowed.' } },
  { id: 'd3-net-035', domain: 3, topics: ['Site-to-Site VPN', 'BGP', 'dynamic routing'], type: 'single', stem: 'A company with Site-to-Site VPN wants automatic route propagation when new on-premises subnets are added. What routing configuration achieves this?', options: [{ id: 'A', text: 'Static routing with manual entries' }, { id: 'B', text: 'BGP dynamic routing' }, { id: 'C', text: 'OSPF over the VPN tunnel' }, { id: 'D', text: 'Route 53 Resolver inbound endpoint' }], correct: ['B'], explanation: 'BGP over VPN: enable route propagation on the VPC route table from the VGW. The on-premises router advertises new subnets via BGP — VGW automatically learns and propagates routes. No manual VPC route table updates needed.', distractors: { A: 'Static routing requires manual route table updates for every new subnet — error-prone and not scalable.', C: 'AWS Site-to-Site VPN supports BGP — not OSPF. OSPF is an interior gateway protocol for within a single network, not across VPN.', D: 'Route 53 Resolver is for DNS resolution — not VPN route propagation or subnet routing.' } },
  { id: 'd3-net-036', domain: 3, topics: ['VPC Traffic Mirroring', 'packet capture', 'IDS'], type: 'single', stem: 'A security team needs to capture all traffic through an EC2 instance for a third-party IDS without affecting the primary traffic path. What provides this?', options: [{ id: 'A', text: 'VPC Flow Logs' }, { id: 'B', text: 'VPC Traffic Mirroring' }, { id: 'C', text: 'Amazon GuardDuty' }, { id: 'D', text: 'AWS CloudTrail' }], correct: ['B'], explanation: 'Traffic Mirroring creates a copy of inbound/outbound traffic from a source ENI and sends it to a target (NLB or ENI). Original traffic is unaffected. The IDS appliance receives the mirrored traffic for deep inspection.', distractors: { A: 'Flow Logs capture metadata (IP, port, bytes, action) — not actual packet payloads needed for deep packet inspection by an IDS.', C: 'GuardDuty uses ML on existing log sources for threat detection — does not provide raw packet capture for custom IDS appliances.', D: 'CloudTrail logs API management calls — not network-level packet captures or flow data.' } },
  { id: 'd3-net-037', domain: 3, topics: ['VPC Lattice', 'service-to-service networking'], type: 'single', stem: 'Multiple teams run microservices in different VPCs and accounts. They need service discovery, connectivity, and access policies without managing PrivateLink per service. What simplifies this?', options: [{ id: 'A', text: 'Transit Gateway for all service traffic' }, { id: 'B', text: 'Amazon VPC Lattice' }, { id: 'C', text: 'AWS Cloud Map for service discovery only' }, { id: 'D', text: 'API Gateway private integrations' }], correct: ['B'], explanation: 'Amazon VPC Lattice provides a consistent application-layer networking plane: service discovery, service-to-service connectivity across VPCs/accounts, SigV4 auth policies, request routing, and observability. No per-service PrivateLink setup needed.', distractors: { A: 'TGW provides Layer 3 VPC routing — not application-layer policies, authentication, or service-level observability.', C: 'Cloud Map provides DNS-based service discovery — does not handle connectivity, access policies, or traffic routing between VPCs.', D: 'API Gateway creates managed API endpoints — designed for north-south API exposure, not east-west microservice mesh networking.' } },
  { id: 'd3-net-038', domain: 3, topics: ['CloudFront', 'TTL', 'cache freshness'], type: 'single', stem: 'CloudFront objects have 24-hour TTL. Users get stale content hours after origin updates. What reduces the maximum stale time?', options: [{ id: 'A', text: 'Increase the TTL further' }, { id: 'B', text: 'Lower the TTL or use Cache-Control headers from origin; use invalidations for immediate content updates' }, { id: 'C', text: 'Use signed URLs to bypass the cache for all requests requiring fresh content' }, { id: 'D', text: 'Switch to a lower-cost CloudFront price class' }], correct: ['B'], explanation: 'To reduce stale content: lower TTL reduces cache duration (more origin requests), configure origin with Cache-Control: max-age=X for content-specific control, or use CloudFront invalidations to purge specific paths immediately.', distractors: { A: 'Higher TTL makes staleness worse — content is cached longer before CloudFront fetches a fresh copy.', C: 'Signed URLs control access authorization — they can bypass cache but it is per-request and does not solve the general freshness problem.', D: 'Price class controls which geographic edge locations are used — not cache duration or content freshness.' } },
  { id: 'd3-net-039', domain: 3, topics: ['VPC IPAM', 'IP address management', 'CIDR conflict'], type: 'single', stem: 'A company with hundreds of VPCs across accounts experiences CIDR conflicts when new VPCs are created with overlapping ranges. What provides centralized IP address management?', options: [{ id: 'A', text: 'Maintain a CIDR tracking spreadsheet shared across teams' }, { id: 'B', text: 'Amazon VPC IPAM' }, { id: 'C', text: 'AWS Organizations SCPs' }, { id: 'D', text: 'Route 53 IPAM records' }], correct: ['B'], explanation: 'Amazon IPAM provides centralized IP address planning, tracking, and enforcement. Assign CIDR pools to OUs and accounts. IPAM can enforce that VPCs allocate CIDRs from their assigned pool, preventing overlaps at creation time.', distractors: { A: 'Spreadsheet tracking is manual, error-prone, and does not enforce or prevent conflicts at creation time.', C: 'SCPs can deny API calls but cannot dynamically check CIDR overlaps against existing VPCs — IPAM provides real-time validation.', D: 'Route 53 IPAM records do not exist — IPAM is a standalone VPC service for IP address management.' } },
  { id: 'd3-net-040', domain: 3, topics: ['VPC Flow Logs', 'custom format', 'additional fields'], type: 'single', stem: 'A security team needs VPC Flow Logs to include packet type (IPv4/IPv6) and flow direction. Are custom format fields supported?', options: [{ id: 'A', text: 'VPC Flow Logs support only a fixed default format' }, { id: 'B', text: 'Yes' }, { id: 'C', text: 'Custom fields are available only when sending logs to CloudWatch Logs, not S3' }, { id: 'D', text: 'Custom fields require an AWS Support request to enable for the specific VPC' }], correct: ['B'], explanation: 'VPC Flow Logs support custom log formats. Choose from available fields including flow-direction, traffic-type (IPv4/IPv6), pkt-src-aws-service, TCP flags, and more. Works for both CloudWatch Logs and S3 destinations.', distractors: { A: 'Custom format is a supported self-service feature — the default format is the starting point, not the only option.', C: 'Custom format works with both CloudWatch Logs and S3 destinations equally.', D: 'Custom log format is configured in the console or CLI without any AWS Support involvement.' } },
  { id: 'd3-net-041', domain: 3, topics: ['Direct Connect', 'hosted connection', 'sub-1Gbps'], type: 'single', stem: 'A company needs 200 Mbps Direct Connect bandwidth. AWS dedicated connections start at 1 Gbps. What provides sub-1Gbps Direct Connect?', options: [{ id: 'A', text: 'AWS dedicated Direct Connect at 1 Gbps' }, { id: 'B', text: 'Direct Connect Hosted Connection via an AWS Partner' }, { id: 'C', text: 'Site-to-Site VPN with bandwidth throttling configured to 200 Mbps as a Direct Connect alternative' }, { id: 'D', text: 'Transit Gateway VPN attachment with bandwidth shaping limited to 200 Mbps for sub-1Gbps connectivity' }], correct: ['B'], explanation: 'Hosted connections (from AWS Direct Connect Partners) provide sub-1 Gbps capacities: 50, 100, 200, 300, 400, 500 Mbps. The partner owns the dedicated port and allocates a capacity slice to the customer.', distractors: { A: 'AWS direct dedicated connections start at 1 Gbps minimum — they cannot be provisioned smaller than 1 Gbps.', C: 'VPN runs over the internet and does not provide Direct Connect-level consistency, low latency, or bandwidth guarantees.', D: 'TGW VPN bandwidth shaping is not equivalent to a Direct Connect connection with dedicated private bandwidth.' } },
  { id: 'd3-net-042', domain: 3, topics: ['Route 53 Resolver DNS Firewall', 'DNS security', 'C2 blocking'], type: 'single', stem: 'A compromised EC2 instance makes DNS queries to malicious C2 domains. How can DNS-level blocking be enforced across the VPC?', options: [{ id: 'A', text: 'Block outbound port 53 in security groups' }, { id: 'B', text: 'Route 53 Resolver DNS Firewall' }, { id: 'C', text: 'Network ACL rules blocking UDP port 53' }, { id: 'D', text: 'GuardDuty with automated Lambda remediation' }], correct: ['B'], explanation: 'Route 53 Resolver DNS Firewall blocks DNS queries to known malicious domains at the VPC level. Configure block/allow lists (custom or AWS-managed threat intel). Applied to all DNS queries from Route 53 Resolver in the VPC.', distractors: { A: 'Blocking port 53 entirely prevents all DNS queries — breaks all legitimate DNS resolution across the VPC.', C: 'NACL blocking all UDP 53 breaks all DNS — cannot selectively block specific domain names at the packet level.', D: 'GuardDuty detects threats after the fact — DNS Firewall proactively blocks malicious DNS queries before they resolve.' } },
  { id: 'd3-net-043', domain: 3, topics: ['ENA Express', 'SRD', 'low latency east-west'], type: 'single', stem: 'A latency-sensitive trading application needs the lowest possible network latency between EC2 instances in the same subnet. What feature achieves sub-microsecond improvements?', options: [{ id: 'A', text: 'Cluster placement group alone' }, { id: 'B', text: 'ENA Express (SRD protocol)' }, { id: 'C', text: 'Elastic Fabric Adapter (EFA)' }, { id: 'D', text: 'SR-IOV passthrough' }], correct: ['B'], explanation: 'ENA Express uses the Scalable Reliable Datagram (SRD) protocol, which provides lower latency and higher bandwidth for EC2-to-EC2 communication compared to standard TCP/ENA. Most effective for same-subnet traffic.', distractors: { A: 'Cluster placement groups reduce physical distance — standard TCP/ENA latency still applies; ENA Express adds on top.', C: 'EFA is for HPC/MPI workloads with OS-bypass for collective operations — ENA Express improves standard socket-based applications.', D: 'SR-IOV is the underlying technology enabling ENA — ENA Express is the specific per-flow protocol improvement.' } },
  { id: 'd3-net-044', domain: 3, topics: ['Egress-Only Internet Gateway', 'IPv6', 'outbound only'], type: 'single', stem: 'EC2 instances with IPv6 addresses need to initiate outbound internet connections but must not receive unsolicited inbound connections. What VPC component provides this?', options: [{ id: 'A', text: 'NAT Gateway' }, { id: 'B', text: 'Egress-Only Internet Gateway' }, { id: 'C', text: 'Internet Gateway with security group' }, { id: 'D', text: 'Virtual Private Gateway' }], correct: ['B'], explanation: 'Egress-Only Internet Gateway (EOIGW) is the IPv6 equivalent of NAT Gateway. IPv6 addresses are globally routable — EOIGW allows outbound IPv6 traffic while preventing unsolicited inbound connections from the internet.', distractors: { A: 'NAT Gateway supports IPv4 only — it cannot handle IPv6 outbound traffic.', C: 'Internet Gateway allows both inbound and outbound — public IPv6 addresses are directly reachable unless security groups block inbound.', D: 'Virtual Private Gateway routes traffic to on-premises via VPN or Direct Connect — not internet egress for IPv6.' } },
  { id: 'd3-net-045', domain: 3, topics: ['VPC peering', 'bandwidth limit', 'exam trap'], type: 'single', stem: 'Is there a dedicated bandwidth limit for VPC peering connections?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'No explicit bandwidth limit' }, { id: 'C', text: 'Yes' }, { id: 'D', text: 'Bandwidth depends on the Direct Connect port speed if using cross-region peering' }], correct: ['B'], explanation: 'VPC peering has no dedicated bandwidth limit. Throughput is bounded by the network bandwidth of the EC2 instances on each end. A 100 Gbps instance can achieve 100 Gbps over a peering connection.', distractors: { A: '1 Gbps is not a VPC peering bandwidth limit — the instance network bandwidth is the constraint.', C: '10 Gbps is also not a documented inter-region peering limit — instance bandwidth determines the cap.', D: 'VPC peering bandwidth is not related to Direct Connect port speeds — they are independent connectivity mechanisms.' } },
]
